INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(24601, 'Luke 18:40', 'Luke', 18, 40, '&nbsp;عيسىٰ ودرېدلو او خلقو له يې حُکم ورکړو چې، ”دے ما له راولئ.“ کله چې هغه نزدې راغے نو تپوس يې ترې وکړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24602, 'Luke 18:41', 'Luke', 18, 41, '&nbsp;”تۀ څۀ غواړې چې زۀ يې ستا دپاره وکړم؟“ هغۀ ووئيل، ”مالِکه، زۀ خپل نظر غواړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24603, 'Luke 18:42', 'Luke', 18, 42, '&nbsp;عيسىٰ هغۀ ته وفرمائيل چې، ”بينا شه، تۀ خپل ايمان بچ کړې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24604, 'Luke 18:43', 'Luke', 18, 43, '&nbsp;نو سمدستى هغه بينا شو او په هغۀ پسې روان شو. او د خُدائ پاک ثنا يې وئيله. او ټولو خلقو چې دا ننداره وليده نو د خُدائ پاک ثنا يې ووئيله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24605, 'Luke 19:1', 'Luke', 19, 1, '&nbsp;بيا عيسىٰ يريحو ته ننوتو او د ښار په مينځ کښې تېرېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24606, 'Luke 19:2', 'Luke', 19, 2, '&nbsp;هلته زکاۍ نومې يو سړے وو. دے د محصولچيانو سردار او ډېر مالداره وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24607, 'Luke 19:3', 'Luke', 19, 3, '&nbsp;د هغۀ دا تلوسه وه چې عيسىٰ به څنګه سړے وى، خو په قد مندرے وو او د ګڼو خلقو له وجې يې هغه ليدلے نۀ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24608, 'Luke 19:4', 'Luke', 19, 4, '&nbsp;نو هغۀ د خلقو نه وړاندې منډه کړه او يوې ټيټې ونې ته وختلو چې هغه ووينى، ځکه چې عيسىٰ هم په دغه طرف روان وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24609, 'Luke 19:5', 'Luke', 19, 5, '&nbsp;او کله چې عيسىٰ هغه ځائ ته راورسېدو نو پورته يې وکتل او وې فرمائيل چې، ”اے زکايه، زر راکوز شه. زۀ ضرور نن ستا کور کښې مېلمه کېږم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24610, 'Luke 19:6', 'Luke', 19, 6, '&nbsp;نو هغه زر راکوز شو او ډېر په خوشحالۍ يې ورته هرکلے ووئيلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24611, 'Luke 19:7', 'Luke', 19, 7, '&nbsp;نو خلقو چې دا وليدل نو ټول ځان سره وغورېدل او وې وئيل، ”هغه د يو ګناه ګار سړى کور ته ورغلو چې ورسره مېلمه شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24612, 'Luke 19:8', 'Luke', 19, 8, '&nbsp;خو زکاۍ ودرېدو او مالِک ته يې ووئيل، ”مالِکه، زۀ خپل نيم مال خوارانو له ورکوم او کۀ ما له چا نه په دوکه باندې څۀ اخستى وى نو هغۀ له به يو په څلور واپس ورکړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24613, 'Luke 19:9', 'Luke', 19, 9, '&nbsp;عيسىٰ هغۀ ته وفرمائيل چې، ”هم نن دې کور ته نجات راغلے دے ځکه چې دے هم د اِبراهيم زوئ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24614, 'Luke 19:10', 'Luke', 19, 10, '&nbsp;ځکه چې اِبن آدم دې له راغلے دے چې ورک شوى ولټوى او بچ يې کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24615, 'Luke 19:11', 'Luke', 19, 11, '&nbsp;د هغوئ لا دې ته غوږ وو چې عيسىٰ ورته يو مِثال ووئيلو ځکه چې هغه اوس يروشلم ته رانزدې وو او د هغوئ دا ګُمان وو چې د خُدائ پاک بادشاهى اوس زر په ښکاره کېدو ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24616, 'Luke 19:12', 'Luke', 19, 12, '&nbsp;هغۀ وفرمائيل، ”د يو لوئ خاندان يو سړے په اوږد سفر يو بل مُلک ته لاړو د دې دپاره چې هغه بادشاهت حاصل کړى او بيا واپس راشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24617, 'Luke 19:13', 'Luke', 19, 13, '&nbsp;خو اول هغۀ خپل لس نوکران راوبلل او هر يو ته يې په دې وينا د سرو زرو يوه يوه سيکه ورکړه چې دوئ پرې سوداګرى کوى ترڅو چې زۀ راواپس نۀ شم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24618, 'Luke 19:14', 'Luke', 19, 14, '&nbsp;خو د خپل مُلک خلقو ورسره کينه کوله او په هغۀ پسې يې يوه جرګه ولېږله چې، مونږ دا سړے خپل بادشاه کېدل نۀ غواړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24619, 'Luke 19:15', 'Luke', 19, 15, '&nbsp;خو بيا هم هغه د بادشاه په حيثيت واپس راغلو او کومو نوکرانو ته چې يې پېسې ورکړې وې هغوئ ته يې سوال جواب ولېږلو چې دا معلومه کړى چې په دوئ کښې هر يو څومره ګټه کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24620, 'Luke 19:16', 'Luke', 19, 16, '&nbsp;وړومبے راغے او وې وئيل، صاحبه، ستا د سرو زرو سيکې لس نورې ګټلى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24621, 'Luke 19:17', 'Luke', 19, 17, '&nbsp;هغۀ جواب ورکړو، شاباش، تۀ ډېر ښۀ نوکر يې. ځکه چې تا په لږو کښې خپل ځان ايمانداره ثابت کړو، تۀ د لسو ښارونو حاکِم شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24622, 'Luke 19:18', 'Luke', 19, 18, '&nbsp;بيا دوېم راغلو او وې وئيل چې، مالِکه، ستا د سرو زرو سيکو پينځۀ نورې ګټلى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24623, 'Luke 19:19', 'Luke', 19, 19, '&nbsp;او هغۀ ته يې ووئيل چې، تۀ هم د پينځو ښارونو حاکِم شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24624, 'Luke 19:20', 'Luke', 19, 20, '&nbsp;بيا بل نوکر راغلو او وې وئيل، مالِکه، دا ستا د سرو زرو سيکه ده. ما دا په رومال کښې انغښتې وه او سمباله کړې مې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24625, 'Luke 19:21', 'Luke', 19, 21, '&nbsp;زۀ ستا نه يرېدم ځکه چې تۀ يو ظالم سړے يې. هغه څۀ اخلى څۀ چې ستا نۀ وى او هغه څۀ رېبى کوم چې تا کَرلى نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24626, 'Luke 19:22', 'Luke', 19, 22, '&nbsp;هغۀ جواب ورکړو، اے بد تميزه. زۀ به هم ستا په خولۀ تا سره اِنصاف وکړم. تا ته دا معلومه وه چې زۀ يو سخت سړے يم او هغه څۀ حاصلوم چې کوم ما نۀ وى ورکړى او هغه څۀ رېبم چې کوم ما نۀ وى کَرلى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24627, 'Luke 19:23', 'Luke', 19, 23, '&nbsp;نو بيا تا ولې زما د سرو زرو سيکه د صرافانو سره نۀ ده اېښې چې بيا ما په واپسۍ کښې سره د ګټې اخستے وے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24628, 'Luke 19:24', 'Luke', 19, 24, '&nbsp;هغۀ حاضرينو ته مخ راواړولو او وې وئيل چې، دغه د سرو زرو سيکه د دۀ نه واخلئ او هغۀ له يې ورکړئ چې د چا سره چې لس دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24629, 'Luke 19:25', 'Luke', 19, 25, '&nbsp;هغوئ جواب ورکړو چې مالِکه، د هغۀ سره خو د اول نه لس دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24630, 'Luke 19:26', 'Luke', 19, 26, '&nbsp;هغۀ هغوئ ته وفرمائيل، زۀ تاسو ته دا وايم چې د چا سره چې څۀ وى هغۀ ته به نور هم ورکړے شى تر دې چې ورسره لا نور زيات شى، خو د چا سره چې څۀ نۀ وى د هغۀ نه به هغه څۀ هم واخستلے شى کوم چې ورسره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24631, 'Luke 19:27', 'Luke', 19, 27, '&nbsp;خو زما هغه دشمنانو چې زۀ بادشاه کېدل نۀ غوښتم، هغوئ راولئ او زما په وړاندې يې قتل کړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24632, 'Luke 19:28', 'Luke', 19, 28, '&nbsp;د دې خبرو کولو نه پس عيسىٰ خپلو مريدانو نه مخکښې يروشلم ته روان وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24633, 'Luke 19:29', 'Luke', 19, 29, '&nbsp;هر کله چې هغه بيتِ‌فګے او بيتِ‌عنياه ته ورنزدې شو کوم چې د زيتُونو په غرۀ ودان دى نو هغۀ دوه مريدان د دې هداياتو سره ولېږل چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24634, 'Luke 19:30', 'Luke', 19, 30, '&nbsp;”دې مخامخ کلى ته ورشئ نو چې څنګه ورننوځئ نو تاسو به يو کوچاڼے تړلے ومومئ چې تر اوسه پرې هيچا لا سورلى نۀ ده کړې. هغه پرانيزئ او دلته يې راولئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24635, 'Luke 19:31', 'Luke', 19, 31, '&nbsp;او کۀ څوک درنه دا تپوس وکړى چې تاسو دا کوچاڼے ولې پرانيزئ نو ورته ووايئ چې زمونږ د مالِک په کار دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24636, 'Luke 19:32', 'Luke', 19, 32, '&nbsp;دواړه په مخه لاړل او هم هغه شان يې وموندل لکه چې عيسىٰ ورته فرمائيلى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24637, 'Luke 19:33', 'Luke', 19, 33, '&nbsp;او کله چې هغوئ کوچاڼے پرانستو نو د دې مالِکانو ترينه تپوس وکړو چې، ”تاسو دا کوچاڼے ولې پرانيزئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24638, 'Luke 19:34', 'Luke', 19, 34, '&nbsp;هغوئ جواب ورکړو چې، ”دا زمونږ د مالِک په کار دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24639, 'Luke 19:35', 'Luke', 19, 35, '&nbsp;او هغوئ کوچاڼے عيسىٰ له راوستو، بيا هغوئ په کوچاڼى باندې خپلې جامې واچولې او عيسىٰ ورباندې سورلى وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24640, 'Luke 19:36', 'Luke', 19, 36, '&nbsp;کله چې هغه په لاره تېرېدو نو خلقو ورته په لار کښې خپلې جامې غوړولې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24641, 'Luke 19:37', 'Luke', 19, 37, '&nbsp;اوس څۀ وخت چې هغه د زيتُونو د غرۀ نه مخ په کوزېدو وو نو ټولو ملګرو او مريدانو يې په هغه ټولو عجيبه معجزو چې هغوئ ليدلى وې د خُدائ پاک ثنا ووئيله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24642, 'Luke 19:38', 'Luke', 19, 38, '&nbsp;”مبارک دے هغه راتلونکے بادشاه چې د مالِک خُدائ په نامه راځى. سلامتى دې وى په آسمان کښې او جلال دې وى په اوچت آسمان کښې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24643, 'Luke 19:39', 'Luke', 19, 39, '&nbsp;ځينو فريسيانو په دې ګڼه کښې عيسىٰ ته ووئيل، ”اُستاذه، خپلو مريدانو ته ووايه چې غلى شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24644, 'Luke 19:40', 'Luke', 19, 40, '&nbsp;عيسىٰ جواب ورکړو، ”زۀ تاسو ته وايم کۀ چرې هغوئ غلى پاتې شى نو کاڼى بوټى به په چغو سر شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24645, 'Luke 19:41', 'Luke', 19, 41, '&nbsp;هر کله چې هغه نزدې راغلو، ښار يې وليدلو نو هغۀ په دې باندې وژړل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24646, 'Luke 19:42', 'Luke', 19, 42, '&nbsp;او وې فرمائيل، ”کۀ چرې نن ورځ تا ته دا معلومه وے چې کومه د خير لاره ده، خو نه، دا ستا د نظر نه پټه ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24647, 'Luke 19:43', 'Luke', 19, 43, '&nbsp;يو وخت به په تا داسې راشى چې ستا دشمنان به ستا محاصره وکړى، هغوئ به ستا نه چاپير شى او د هرې خوا نه به دې راګېر کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24648, 'Luke 19:44', 'Luke', 19, 44, '&nbsp;نو تاسو به سره د خپلو بچو يو ځائ په زمکه راګزار کړى او ستا يو کاڼے به هم د بل کاڼى دپاسه پرې نۀ ږدى ځکه چې تاسو د خُدائ د خلاصون هغه مقرر وخت ونۀ پېژندلو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24649, 'Luke 19:45', 'Luke', 19, 45, '&nbsp;عيسىٰ بيا د خُدائ کور ته ورننوتو او هغۀ هغه ټول خلق چې د خُدائ په کور کښې يې سوداګرى کوله، وشړل', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24650, 'Luke 19:46', 'Luke', 19, 46, '&nbsp;او ورته يې وفرمائيل، ”صحيفې فرمائى چې، ”زما کور به د دُعا کور بللے شى،“ خو تاسو ترېنه د ډاکوانو اډه جوړه کړې ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24651, 'Luke 19:47', 'Luke', 19, 47, '&nbsp;د خُدائ په کور کښې به هره ورځ عيسىٰ تعليم ورکولو. او مشران اِمامان او د شرعې عالمان د دۀ د وژلو په تلاش کښې وُو چې د اولسى مشرانو مرسته هم ورسره وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24652, 'Luke 19:48', 'Luke', 19, 48, '&nbsp;خو هغوئ په دې کښې بې‌وسه وُو، ځکه چې د خلقو د عيسىٰ په خبرو يقين وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24653, 'Luke 20:1', 'Luke', 20, 1, '&nbsp;يوه ورځ چې عيسىٰ د خُدائ په کور کښې خلقو له تعليم ورکولو او ورته يې زيرے اورولو نو مشران اِمامان، د شرعې عالمان او د قوم مشران ورله راغلل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24654, 'Luke 20:2', 'Luke', 20, 2, '&nbsp;او هغوئ ورته ووئيل، ”مونږ ته ووايه چې تۀ دا کارونه په کوم اختيار کوې؟ او دا اختيار تا له چا درکړے دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24655, 'Luke 20:3', 'Luke', 20, 3, '&nbsp;عيسىٰ هغوئ له جواب ورکړو، ”زۀ هم ستاسو نه يو تپوس کوم، تاسو يې جواب راکړئ', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24656, 'Luke 20:4', 'Luke', 20, 4, '&nbsp;چې د يحيىٰ بپتسمه د آسمان د طرف نه وه او کۀ د انسان؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24657, 'Luke 20:5', 'Luke', 20, 5, '&nbsp;په دې هغوئ د يو بل سره په بحث شول چې، ”کۀ چرې مونږ ووايو چې د آسمان نه، نو هغه به راته ووائى چې بيا تاسو په هغۀ ايمان ولې رانۀ وړو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24658, 'Luke 20:6', 'Luke', 20, 6, '&nbsp;خو کۀ چرې مونږ ووايو چې د انسانانو د طرف نه وه، نو ټول خلق به مونږ سنګسار کړى ځکه چې هغوئ دا منى چې يحيىٰ نبى وو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24659, 'Luke 20:7', 'Luke', 20, 7, '&nbsp;نو هغوئ جواب ورکړو چې، ”مونږ خبر نۀ يُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24660, 'Luke 20:8', 'Luke', 20, 8, '&nbsp;نو عيسىٰ ورته وفرمائيل، ”بيا به زۀ هم دا درته ونۀ وايم چې زۀ په کوم اختيار دا کارونه کوم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24661, 'Luke 20:9', 'Luke', 20, 9, '&nbsp;نو بيا عيسىٰ خلقو ته دا مِثال تير کړو چې، ”يو زميندار وو چې د انګورو باغ يې ولګولو، او زميندارانو له يې په اجاره ورکړو او يو بل مُلک ته د ډيرې مودې دپاره لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24662, 'Luke 20:10', 'Luke', 20, 10, '&nbsp;کله چې موسم راغلو نو هغۀ يو نوکر اجاره دارو له ورولېږلو چې د هغوئ نه د هغۀ د انګورو د پېداوار برخه وصول کړى خو زميندارو هغه ښۀ ووهلو او خالى لاس يې واپس ولېږلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24663, 'Luke 20:11', 'Luke', 20, 11, '&nbsp;هغۀ بيا بل نوکر ورولېږلو خو هغوئ هغه هم ووهلو او بې‌عزته يې کړو، او تش لاس يې واپس ولېږلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24664, 'Luke 20:12', 'Luke', 20, 12, '&nbsp;هغۀ بيا درېم سړے ورولېږلو خو هغه يې هم زخمى کړو، او بهر يې وغورزولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24665, 'Luke 20:13', 'Luke', 20, 13, '&nbsp;بيا د انګورو د باغ مالِک ووئيل چې اوس ما له څۀ کول په کار دى؟ زۀ به خپل خوږ زوئ ورولېږم. شايد چې د دۀ خاطر وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24666, 'Luke 20:14', 'Luke', 20, 14, '&nbsp;خو هر کله چې اجاره دارو هغه وليدو نو يو بل ته يې ووئيل، دا د باغ وارث دے، راځئ چې مړ يې کړو او ميراث به يې مونږ ته پاتې شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24667, 'Luke 20:15', 'Luke', 20, 15, '&nbsp;نو اجاره دارو هغه د انګورو د باغ نه بهر وغورزولو او مړ يې کړو. نو بيا تاسو دا ووايئ چې د انګورو د باغ مالِک به د هغوئ سره څۀ وکړى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24668, 'Luke 20:16', 'Luke', 20, 16, '&nbsp;هغه به راشى او دا ټول اجاره دار به مړۀ کړى او د انګورو باغ به بل چا له ورکړى.“ هر کله چې هغوئ دا واورېدل نو وې وئيل، ”خُدائ مۀ کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24669, 'Luke 20:17', 'Luke', 20, 17, '&nbsp;خو عيسىٰ ورته نېغ نېغ وکتل او وې فرمائيل، ”نو بيا د صحيفو د دې عبارت څۀ مطلب دے، ”کوم کاڼے چې ګِلکارانو رد کړے وو هم هغه د ګوټ سر کاڼے شو“؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24670, 'Luke 20:18', 'Luke', 20, 18, '&nbsp;هر څوک چې د دې کاڼى سره تيندک وخورى هغه به ټوټې ټوټې شى، او کۀ په هر چا دا راپرېوځى نو هغه به ريز مريز کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24671, 'Luke 20:19', 'Luke', 20, 19, '&nbsp;د شرعې عالمانو او مشرانو اِمامانو غوښتل چې هغۀ ته هم په هغه وخت لاس ورواچوى ځکه چې هغوئ ته دا پته ولګېدله چې دا مِثال د هغوئ په خلاف دے خو هغوئ ورسره څۀ ونۀ کړل ځکه چې هغوئ د خلقو نه يرېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24672, 'Luke 20:20', 'Luke', 20, 20, '&nbsp;نو هغوئ په دې لټون کښې وُو چې څنګه به يې راګېر کړو. نو جاسوسان يې پټ د صادقانو په جامه کښې ورولېږل چې په هغۀ کښې څۀ داسې خبرې راپېدا کړى چې د هغې په بهانه هغه راګېر کړى او ګورنر ته يې حواله کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
